function stripDiacritics(value) {
        return String(value || "")
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g, "");
    }

    function fixMojibake(value) {
        const text = String(value || "");
        if (!/[ÃÂ]/.test(text)) {
            return text;
        }
        try {
            const bytes = Uint8Array.from(Array.from(text, (character) => character.charCodeAt(0)));
            return new TextDecoder("utf-8").decode(bytes);
        } catch (error) {
            return text;
        }
    }

    function normalizeWhitespace(value) {
        return fixMojibake(value).replace(/\s+/g, " ").trim();
    }

    function normalizeSearchValue(value) {
        return stripDiacritics(normalizeWhitespace(value)).toLowerCase();
    }

    function replaceWord(text, source, target) {
        const pattern = new RegExp(`\\b${source}\\b`, "gi");
        return text.replace(pattern, (match) => {
            if (match === match.toUpperCase()) return target.toUpperCase();
            if (match.charAt(0) === match.charAt(0).toUpperCase()) {
                return target.charAt(0).toUpperCase() + target.slice(1);
            }
            return target;
        });
    }

