    function upgradeWixImageUrl(url, { width, height, quality } = WIX_QUALITY_PROFILE) {
        const value = String(url || "").trim();
        if (!value || !/static\.wixstatic\.com/i.test(value)) {
            return value;
        }

        return value.replace(
            /\/v1\/fit\/w_\d+,h_\d+,q_\d+\/file\./i,
            `/v1/fit/w_${width},h_${height},q_${quality}/file.`
        );
    }

    const productEntries = rawCatalog
        .filter((item) => !EXCLUDED_PRODUCT_KEYS.has(normalizeKey(item.slug || item.title)))
        .map((item, index) => {
            const key = normalizeKey(item.slug || item.title);
            const priceValue = PRODUCT_PRICE_OVERRIDES[key] ?? item.price;
            const numericPrice = Number(priceValue) || 0;
            const displayPrice = PRODUCT_PRICE_LABEL_OVERRIDES[key] || `S/${priceValue}`;
            const lines = splitLines(item.description || "");
            const title = polishDisplayText(item.title);
            const description = polishDisplayText(item.description || "");
            const category = inferCategory(title, description);
            const enhancedPrimaryImage = LOCAL_ENHANCED_PRIMARY_IMAGES[key] || "";
            const images = Array.isArray(item.images)
                ? item.images
                    .filter(Boolean)
                    .map((imageUrl) => upgradeWixImageUrl(imageUrl))
                : [];
            const limitedImages = images.slice(0, MAX_PRODUCT_GALLERY_IMAGES);
            const gallery = limitedImages.length ? [...limitedImages] : [];

            if (enhancedPrimaryImage) {
                if (gallery.length) {
                    gallery[0] = enhancedPrimaryImage;
                } else {
                    gallery.push(enhancedPrimaryImage);
                }
            }

            const primaryImage = enhancedPrimaryImage || limitedImages[0] || "";
            const hoverImage = gallery[1] || gallery[0] || primaryImage;

            return [
                key,
                {
                    title,
                    price: displayPrice,
                    priceValue: numericPrice,
                    text: buildText(title, lines),
                    image: primaryImage,
                    hoverImage,
                    gallery,
                    alt: title,
                    material: "PLA",
                    size: buildSize(lines),
                    delivery: inferDelivery(numericPrice),
                    category,
                    colors: inferColors(key, title, description, category),
                    sourceUrl: fixMojibake(item.url),
                    sourceSlug: key,
                    fullDescription: description
                }
            ];
        });

    const productData = Object.fromEntries(productEntries);

    function uniqueGalleryPaths(paths) {
        return Array.from(new Set((Array.isArray(paths) ? paths : []).filter(Boolean)));
    }

    function mergeProductGallery(product, extraImages) {
        if (!product) return;

        const mergedGallery = uniqueGalleryPaths([
            product.image,
            ...(Array.isArray(product.gallery) ? product.gallery : []),
            ...(Array.isArray(extraImages) ? extraImages : [])
        ]);

        product.gallery = mergedGallery;
        product.image = mergedGallery[0] || product.image || "";
        product.hoverImage = mergedGallery[1] || mergedGallery[0] || product.image;
    }

    function replaceProductGallery(product, galleryImages) {
        if (!product) return;

        const cleanGallery = uniqueGalleryPaths(galleryImages);
        if (!cleanGallery.length) return;

        product.gallery = cleanGallery;
        product.image = cleanGallery[0];
        product.hoverImage = cleanGallery[1] || cleanGallery[0];
    }

    function createManualProduct({
        key,
        title,
        price,
        priceLabel,
        text,
        size,
        fullDescription,
        gallery,
        category = "Decorativo",
        material = "PLA",
        colors = ["gris"]
    }) {
        const galleryImages = uniqueGalleryPaths(gallery);
        const numericPrice = Number(price) || 0;

        return [
            key,
            {
                title: polishDisplayText(title),
                price: priceLabel || `S/${price}`,
                priceValue: numericPrice,
                text: polishDisplayText(text),
                image: galleryImages[0] || "",
                hoverImage: galleryImages[1] || galleryImages[0] || "",
                gallery: galleryImages,
                alt: polishDisplayText(title),
                material,
                size,
                delivery: inferDelivery(numericPrice),
                category: polishDisplayText(category),
                colors,
                sourceUrl: "",
                sourceSlug: key,
                fullDescription: splitLines(fullDescription).join("\n")
            }
        ];
    }

